xhtml:div.style:
width:100%;
height:100%;
display:flex;
align-items:center;
justify-content:center;
background:#f7f7f7;

width:340px;
padding:25px;
text-align:center;
background:white;
border:2px dashed #007BFF;
border-radius:10px;

svg.script:
const fileInput =
    document.getElementById("fileInput");

const openBtn =
    document.getElementById("openBtn");

const launcher =
    document.getElementById("launcher");

const app =
    document.getElementById("app");

const status =
    document.getElementById("status");

let htmlContent = "";

fileInput.addEventListener("change", async (event) => {

    const file = event.target.files[0];

    if (!file) return;

    htmlContent = await file.text();

    status.textContent =
        "Loaded: " + file.name;
});


openBtn.addEventListener("click", async () => {

    if (!htmlContent) {
        alert("Select an HTML file first.");
        return;
    }

    /*
     * Parse the uploaded HTML.
     */
    const parser = new DOMParser();

    const parsed =
        parser.parseFromString(
            htmlContent,
            "text/html"
        );


    /*
     * Copy the HTML body into our SVG app.
     */
    app.innerHTML = parsed.body.innerHTML;


    /*
     * Copy the CSS from the uploaded document.
     */
    for (const style of parsed.querySelectorAll("style")) {

        const newStyle =
            document.createElementNS(
                "http://www.w3.org/1999/xhtml",
                "style"
            );

        newStyle.textContent =
            style.textContent;

        app.prepend(newStyle);
    }


    /*
     * Show the application.
     */
    launcher.style.display = "none";
    app.style.display = "block";


    /*
     * Execute scripts from the uploaded HTML.
     */
    for (const oldScript of
         parsed.querySelectorAll("script")) {

        const script =
            document.createElementNS(
                "http://www.w3.org/1999/xhtml",
                "script"
            );

        if (oldScript.src) {
            script.src = oldScript.src;
        } else {
            script.textContent =
                oldScript.textContent;
        }

        document.documentElement.appendChild(script);
    }

});
